'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),fmt=d=>d.split('-').reverse().join('/'),number=n=>n.toLocaleString('pt-BR');
const source=(url,label='Fonte oficial ↗')=>`<a class="source" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)}</a>`;
let data,audit,filtered=[],periodDocs=[],periodSessions=[],page=1,repeatLimit=8,sessionLimit=12;const size=8;
const range=()=>`${fmt($('#from').value)} a ${fmt($('#to').value)}`;
function inPeriod(d){return d>=$('#from').value&&d<=$('#to').value;}
function ownDocs(p){return periodDocs.filter(d=>d.authorIds.includes(p.id));}
function updatePeriod(){if(!data)return;const from=$('#from').value,to=$('#to').value;if(!from||!to||from>to||from<data.start||to>data.end){$('#period-error').textContent='Escolha um intervalo válido dentro da cobertura.';return;}$('#period-error').textContent='';periodDocs=data.documents.filter(d=>inPeriod(d.date));periodSessions=data.sessions.filter(s=>inPeriod(s.date));sessionLimit=12;const votes=periodSessions.reduce((n,s)=>n+s.votes.length,0);$('#stats').innerHTML=[[data.people.length,'participantes cadastrados',data.sources.roster],[periodDocs.length,'propostas no período','#propostas'],[periodSessions.length,'sessões plenárias','#sessoes'],[votes,'registros de votação','#sessoes']].map(([n,t,u])=>`<div class="stat"><strong>${number(n)}</strong><span>${t}</span><a href="${esc(u)}">Conferir registros ↗</a></div>`).join('');$('#session-period').textContent=range();renderPeople();renderSessions();filter();renderRepeats();}
function filter(){if(!data)return;const q=norm($('#search').value.trim()),id=$('#author').value,cat=$('#category').value;filtered=periodDocs.filter(d=>(!q||d.search.includes(q))&&(!id||d.authorIds.includes(id))&&(!cat||d.category===cat));page=1;renderDocs();}
function documentCard(d){return `<article class="doc"><div><span class="tag" data-cat="${esc(d.category)}">${esc(d.category)}</span><h3>${esc(d.title)}</h3><p>${esc(d.text.length>245?d.text.slice(0,245)+'…':d.text)}</p><p class="meta">Autoria: ${esc(d.authors)}</p><details><summary>Ler proposta e situação</summary><p>${esc(d.text)}</p><p class="meta">${esc(d.meta)}</p><p class="meta">Categoria calculada automaticamente. Confira a fonte.</p></details></div><div class="doc-side"><span>Protocolo<br><strong>${fmt(d.date)}</strong></span>${source(d.url,'Ver proposta oficial ↗')}</div></article>`;}
function renderDocs(){const max=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,max);$('#result-count').textContent=`${number(filtered.length)} propostas · ${range()}`;$('#documents').innerHTML=filtered.slice((page-1)*size,page*size).map(documentCard).join('')||'<div class="empty"><strong>Nenhum registro nesta busca.</strong><p>Tente outra grafia ou remova filtros. Isso não significa ausência de trabalho fora da base coletada.</p></div>';$('#page').textContent=`${page} de ${max}`;$('#prev').disabled=page===1;$('#next').disabled=page===max;}
function attendanceFor(p){return periodSessions.map(s=>({s,a:s.attendance.find(a=>a.personIds.includes(p.id))}));}
function profile(id){const p=data.people.find(p=>p.id===id),docs=ownDocs(p),records=attendanceFor(p);const count=records.reduce((o,{a})=>{const key=a?a.status:'Sem registro';o[key]=(o[key]||0)+1;return o;},{});const votes=periodSessions.flatMap(s=>s.votes.flatMap(v=>v.rows.filter(r=>r.personIds.includes(id)).map(r=>({s,v,r}))));$('#profile-content').innerHTML=`<div class="profile-head"><img src="${esc(p.photo)}" alt="Retrato oficial de ${esc(p.name)}"><div><p class="eyebrow">PARTICIPANTE DA LEGISLATURA · ${esc(p.party)}</p><h2>${esc(p.name)}</h2>${source(p.url,'Ficha oficial ↗')}</div></div><p><strong>${number(docs.length)} propostas</strong> com autoria identificada entre ${range()}.</p><p class="muted">Contagem calculada na base. Não é avaliação de desempenho nem declaração de exercício em todo o período.</p><button class="primary" id="show-author">Ler propostas deste vereador →</button><h3>Presenças registradas</h3><div class="presence-summary">${Object.entries(count).map(([k,v])=>`<span><strong>${v}</strong> ${esc(k)}</span>`).join('')}</div><p class="muted">Contagens nominais, sem inferir comparecimento obrigatório durante licenças ou substituições. Veja as fontes abaixo.</p><details><summary>Conferir sessão por sessão (${records.length})</summary>${records.map(({s,a})=>`<div class="profile-row">${source(s.url,s.title)}<br><strong>${esc(a?a.status:'Sem registro nominal — não interpretado como ausência')}</strong></div>`).join('')}</details><details><summary>Conferir votos publicados (${votes.length})</summary>${votes.map(({s,v,r})=>`<div class="profile-row">${fmt(s.date)} · ${esc(v.title)}<br><strong>${esc(r.vote)}</strong> · ${source(v.url,'Ver voto oficial ↗')}</div>`).join('')||'<p>Sem voto nominal identificado neste período.</p>'}</details>`;$('#show-author').onclick=()=>{$('#author').value=id;$('#search').value='';$('#category').value='';filter();$('#profile').close();location.hash='propostas';};$('#profile').showModal();}
function renderPeople(){$('#people').innerHTML=data.people.map(p=>`<button class="person" data-person="${esc(p.id)}" aria-label="Ver perfil de ${esc(p.name)}"><div class="person-top"><img loading="lazy" src="${esc(p.photo)}" alt=""><div><h3>${esc(p.name)}</h3><small>${esc(p.party)} · cadastro da legislatura</small></div></div><div class="person-bottom"><strong>${number(ownDocs(p).length)} propostas no período</strong><span>Ver fontes ↗</span></div></button>`).join('');document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>profile(b.dataset.person));}
function renderSessions(){$('#sessions').innerHTML=periodSessions.slice(0,sessionLimit).map(s=>`<details class="session"><summary>${esc(s.title)} <span class="subtle-chip">${s.attendance.length} registros nominais</span></summary><div class="session-content">${source(s.url,'Abrir sessão oficial ↗')}<p class="muted">Estados reproduzidos da fonte. Quem não aparece não é considerado ausente pelo Radar.</p><div class="attendance">${s.attendance.map(a=>`<div>${esc(a.name)}<span>${esc(a.status)}</span></div>`).join('')||'<p>Sem registro nominal disponível.</p>'}</div><h3>Votações nominais publicadas</h3>${s.votes.map(v=>`<details class="vote"><summary>${esc(v.title)}</summary><div class="vote-table">${v.rows.map(r=>`<div><span>${esc(r.name)}</span><strong>${esc(r.vote)}</strong></div>`).join('')}</div>${source(v.url,'Conferir registro de votos ↗')}${v.documentUrl?' · '+source(v.documentUrl,'Ler matéria ↗'):''}</details>`).join('')||'<p class="muted">Nenhuma votação nominal extraída desta página.</p>'}</div></details>`).join('')||'<p class="empty">Nenhuma sessão coletada para este intervalo.</p>';if(periodSessions.length>sessionLimit){$('#sessions').insertAdjacentHTML('beforeend',`<button id="more-sessions" class="text-button">Mostrar mais sessões (${periodSessions.length-sessionLimit} restantes) ↓</button>`);$('#more-sessions').onclick=()=>{sessionLimit+=12;renderSessions();};}}
function renderRepeats(){if(!data)return;const q=norm($('#repeat-search').value.trim()),allowed=new Map(periodDocs.map(d=>[d.url,d]));const groups=data.repeatedRequests.map(g=>({...g,docs:g.documents.filter(u=>allowed.has(u)).map(u=>allowed.get(u))})).filter(g=>g.docs.length>=2&&new Set(g.docs.map(d=>d.date)).size>=2&&(!q||norm(g.street+' '+g.topic).includes(q)));$('#repeat-count').textContent=`${number(groups.length)} grupos no período selecionado · contagens calculadas`;$('#repeat-results').innerHTML=groups.slice(0,repeatLimit).map(g=>`<details class="repeat"><summary><span><strong>${esc(g.street)}</strong><small>${esc(g.topic)}</small></span><span class="repeat-number">${g.docs.length} pedidos <span>↓</span></span></summary><p class="muted">Agrupamento automático. Pode incluir trechos e situações diferentes. Não comprova falta de atendimento.</p>${g.docs.sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<div class="profile-row"><strong>${fmt(d.date)}</strong> · ${esc(d.authors)}<br>${esc(d.title)} · ${source(d.url,'Ler pedido ↗')}<p>${esc(d.text.slice(0,260))}${d.text.length>260?'…':''}</p></div>`).join('')}</details>`).join('')||'<p class="empty">Nenhum grupo encontrado. Nem todo logradouro ou assunto é reconhecido automaticamente.</p>';$('#repeat-more').hidden=groups.length<=repeatLimit;}
function renderAudit(){$('#audit-results').innerHTML=audit.samples.map(s=>`<article class="audit-card"><span class="tag">${s.match?'Conferido: coincide':'Comparação pendente'}</span><h3>${fmt(s.date)} · ${esc(s.type)}</h3><p>${esc(s.result)}</p>${source(s.source,s.match?'Conferir ata oficial ↗':'Consultar atas publicadas ↗')} · ${source(s.session,'Conferir sessão ↗')}</article>`).join('');}
async function loadFile(name){const embedded=document.getElementById(name);if(embedded)return JSON.parse(embedded.textContent);const r=await fetch(name);if(!r.ok)throw new Error('Não foi possível carregar '+name);return r.json();}
async function init(){try{[data,audit]=await Promise.all([loadFile('data.json'),loadFile('audit.json')]);if(data.schemaVersion!==2)throw new Error('Base incompatível');data.people.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));data.documents.forEach(d=>d.search=norm(d.text+' '+d.title+' '+d.authors));$('#from').min=$('#to').min=data.start;$('#from').max=$('#to').max=data.end;$('#from').value=data.start;$('#to').value=data.end;$('#hero-period').textContent=`${fmt(data.start)} — ${fmt(data.end)}`;$('#coverage-copy').innerHTML=`<strong>Cobertura: ${fmt(data.start)} a ${fmt(data.end)}.</strong> Propostas por protocolo e sessões plenárias. A informação ausente não vira falta. <a href="#auditoria">Veja a conferência e os limites →</a>`;$('#author').innerHTML='<option value="">Todos os autores</option>'+data.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');const checked=new Date(data.collectedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});$('#collected').textContent=`Última coleta concluída: ${checked} (Brasília). Cobertura de ${fmt(data.start)} a ${fmt(data.end)}. ${data.documentCoverage.reduce((n,r)=>n+r.pages,0)} páginas de documentos percorridas. Atualização da página não inicia coleta.`;renderAudit();updatePeriod();const age=Date.now()-new Date(data.collectedAt).getTime();if(age>48*3600000)$('#coverage-copy').insertAdjacentHTML('beforeend',' <strong>Atenção: a última coleta tem mais de 48 horas. Consulte o histórico de atualização.</strong>');}catch(e){$('#stats').innerHTML='<p role="alert">Não foi possível carregar a base. Nenhum total foi inferido. Recarregue a página ou consulte a fonte oficial.</p>';console.error(e);}}
$('#search').addEventListener('input',filter);$('#author').addEventListener('change',filter);$('#category').addEventListener('change',filter);$('#from').addEventListener('change',updatePeriod);$('#to').addEventListener('change',updatePeriod);$('#all-period').onclick=()=>{if(data){$('#from').value=data.start;$('#to').value=data.end;updatePeriod();}};$('#clear').onclick=()=>{$('#search').value='';$('#author').value='';$('#category').value='';filter();};$('#prev').onclick=()=>{page--;renderDocs();};$('#next').onclick=()=>{page++;renderDocs();};$('#repeat-search').oninput=()=>{repeatLimit=8;renderRepeats();};$('#repeat-more').onclick=()=>{repeatLimit+=8;renderRepeats();};$('#close-profile').onclick=()=>$('#profile').close();$('#export').onclick=()=>{if(!data)return;const clean=filtered.map(({search,...d})=>d),payload={periodo:{inicio:$('#from').value,fim:$('#to').value},coleta:data.collectedAt,criterio:'Resultados filtrados; grupos calculados automaticamente; fontes em cada registro',registros:clean};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='radar-blumenau-busca.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};init();
